from collections import deque
cells=[(r,c) for r in range(4) for c in range(4)]+[(4,3),(5,3)]
idx={p:i for i,p in enumerate(cells)}
start=sum(1<<idx[p] for p in [(1,1),(2,0),(2,1),(3,2),(4,1)])
target=1<<idx[(5,3)]
moves=[]
for i,(r,c) in enumerate(cells):
 for dr,dc in [(2,0),(-2,0),(0,2),(0,-2)]:
  mid=(r+dr//2,c+dc//2); dst=(r+dr,c+dc)
  if mid in idx and dst in idx:
   j,k=idx[mid],idx[dst]
   moves.append((i,j,k))
q=deque([start]); prev={start:None}
while q:
 s=q.popleft()
 if s==target:break
 for i,j,k in moves:
  if s>>i&1 and s>>j&1 and not(s>>k&1):
   t=s^(1<<i)^(1<<j)^(1<<k)
   if t not in prev:
    prev[t]=(s,(i,j,k));q.append(t)
print(len(prev), start in prev, target in prev)
if target in prev:
 path=[];s=target
 while prev[s]:
  old,m=prev[s];path.append(m);s=old
 path=path[::-1]
 for m in path: print([cells[z] for z in m])

